function validate(input) {
  const [{ course_completions = [] }] = input;
  const taken = new Set(), days = new Set(), nameOf = new Map(), idOf = new Map();
  for (const [user, course, name, date, rating] of course_completions) {
    if ([user, course, name, date, rating].includes(null)) return 'No column may be null.';
    if (taken.has(`${user}|${course}`)) return `User ${user} finishes course ${course} twice.`;
    taken.add(`${user}|${course}`);
    if (days.has(`${user}|${date}`)) return `User ${user} finishes two courses on ${date}.`;
    days.add(`${user}|${date}`);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `completion_date ${date} must look like 2024-01-31.`;
    if (!(Number.isInteger(rating) && rating >= 1 && rating <= 5)) return `course_rating ${rating} must be 1 to 5.`;
    const key = String(name).toLowerCase();
    if (nameOf.has(course) && nameOf.get(course) !== name) return `Course ${course} has two names.`;
    if (idOf.has(key) && idOf.get(key) !== course) return `Two courses are named ${name}.`;
    nameOf.set(course, name);
    idOf.set(key, course);
  }
  return null;
}

