function generate(rand, size) {
  const small = size === 'small';
  const pick = n => Math.floor(rand() * n);
  const names = ['Python Basics', 'SQL Fundamentals', 'JavaScript', 'React Basics', 'Node.js', 'Docker', 'AWS Fundamentals', 'Data Science', 'Machine Learning', 'Git Essentials', 'Linux Shell', 'Kubernetes'];
  const pool = small ? 7 : names.length;
  const day = offset => new Date(Date.UTC(2024, 0, 1) + offset * 86400000).toISOString().slice(0, 10);
  const course_completions = [];
  let budget = small ? pick(9) : 2000;
  for (let user = 1; budget > 0; user++) {
    const count = Math.min(budget, pool, small ? (rand() < 0.7 ? 5 + pick(3) : 1 + pick(4)) : 3 + pick(9));
    budget -= count;
    // Courses follow a loose common path (index plus noise), so the same transitions recur across users.
    const path = [...Array(pool).keys()].map(i => [i + rand() * 3, i]).sort((x, y) => x[0] - y[0]).slice(0, count).map(p => p[1]);
    const strong = rand() < 0.65;
    const ratings = strong ? [3, 4, 4, 5, 5] : [1, 2, 3, 4, 5];
    const rows = [];
    let offset = pick(60);
    for (const course of path) {
      rows.push([user, 101 + course, names[course], day(offset), ratings[pick(ratings.length)]]);
      offset += 1 + pick(40);
    }
    // Rows are stored by course_id, so the chronological order differs from the row order.
    rows.sort((x, y) => x[1] - y[1]);
    course_completions.push(...rows);
  }
  return [{ course_completions }];
}
